/**
 * @deepseek-ai/dsh-settings overlay (minimal).
 *
 * Honest overlay: the real package (packages/settings/settings) is a full
 * settings-provider service (register/watch/scope) over a cordis plugin
 * chain. What the agent-loop proof requires is the two VALUE imports the
 * AgentLoop constructor uses: {@link settingsNamespace} (brand validation,
 * real) and {@link installSettingsSection} (the real registration path —
 * which resolves through `ctx.inject(['settings'], …)`; on the NodeWorkerJsHost
 * shim the `settings` service is never provided, so the registration body is
 * inert and the loop keeps its composition entry). A real settings provider
 * (backend + register/watch) is a documented NEEDS.
 *
 * @module @deepseek-ai/dsh-settings
 */

/** Namespace pattern the real package enforces (lowercase, kebab). */
const NAMESPACE_PATTERN = /^[a-z][a-z0-9-]*$/

/**
 * Brand a raw string as a SettingsNamespace.
 * @param value - candidate namespace; lowercase kebab-case, as in plugin short names.
 * @returns the branded namespace.
 */
export function settingsNamespace(value) {
  if (!NAMESPACE_PATTERN.test(value)) {
    throw new TypeError(`settings namespace "${value}" must match ${String(NAMESPACE_PATTERN)}`)
  }
  return value
}

/**
 * Install one settings section owned by the calling context. Resolves through
 * `ctx.inject(['settings'], …)`; with no settings provider live, the
 * registration body never runs and `hooks.setSource`/`hooks.onChange` are
 * never invoked — the owner keeps its composition entry (the honest minimal
 * behavior on this host).
 *
 * @param ctx - owner context.
 * @param ns - branded settings namespace.
 * @param schema - section schema (schemastery; unused when no provider resolves).
 * @param entry - the owner's composition-layer entry.
 * @param hooks - setSource/onChange/validate callbacks.
 */
export function installSettingsSection(ctx, ns, schema, entry, hooks) {
  ctx.inject(['settings'], (sctx) => {
    const scope = sctx.settings.register(ns, schema, {
      base: entry,
      ...hooks.validate === undefined ? {} : { validate: hooks.validate },
    })
    hooks.setSource(() => scope.get())
    sctx.effect(() => () => {
      hooks.setSource(() => entry)
      hooks.onChange()
    })
    hooks.onChange()
    scope.watch(() => {
      hooks.onChange()
    })
  })
}
